/* Assignment 7: FIFO, LRU and Optimal page replacement.
 * FIFO evicts in load order while LRU timestamps every successful access.
 * The live wrapper feeds identical patient references to both independent caches.
 * Optimal is included only as an offline reference for the manual demonstration. */
#include "common.h"
#include <stdio.h>

static int find_frame(const CacheState *s,int page){for(int i=0;i<s->size;i++)if(s->frames[i]==page)return i;return -1;}
int fifo_access(CacheState *s,int page){if(find_frame(s,page)>=0)return 1;int slot=-1;for(int i=0;i<s->size;i++)if(s->frames[i]<0){slot=i;break;}if(slot<0){slot=s->next;s->next=(s->next+1)%s->size;}else if(slot==s->next)s->next=(s->next+1)%s->size;s->frames[slot]=page;return 0;}
int lru_access(CacheState *s,int page){int slot=find_frame(s,page);s->clock++;if(slot>=0){s->stamp[slot]=s->clock;return 1;}for(int i=0;i<s->size;i++)if(s->frames[i]<0){slot=i;break;}if(slot<0){slot=0;for(int i=1;i<s->size;i++)if(s->stamp[i]<s->stamp[slot])slot=i;}s->frames[slot]=page;s->stamp[slot]=s->clock;return 0;}
int optimal_faults(const int refs[],int count,int frames){int f[MAX_PATIENTS],faults=0;for(int i=0;i<frames;i++)f[i]=-1;for(int i=0;i<count;i++){int hit=0;for(int j=0;j<frames;j++)if(f[j]==refs[i])hit=1;if(hit)continue;faults++;int slot=-1;for(int j=0;j<frames;j++)if(f[j]<0){slot=j;break;}if(slot<0){int far=-1;for(int j=0;j<frames;j++){int k;for(k=i+1;k<count;k++)if(refs[k]==f[j])break;if(k>far){far=k;slot=j;}}}f[slot]=refs[i];}return faults;}
void cache_access_shared(int id){sem_wait(&g_shm->cache_mutex);int fh=fifo_access(&g_shm->fifo,id),lh=lru_access(&g_shm->lru,id);if(fh)g_shm->fifo_hits++;else g_shm->fifo_misses++;if(lh)g_shm->lru_hits++;else g_shm->lru_misses++;event_log("CACHE",id,"FIFO=%s LRU=%s",fh?"hit":"miss",lh?"hit":"miss");sem_post(&g_shm->cache_mutex);}
int cache_next_shared(void){static const int refs[]={1,2,3,4,2,1,5,6,2,1,2,3,7,6,3,2,1,2,3,6};sem_wait(&g_shm->cache_mutex);unsigned long at=g_shm->cache_lookups++;int slot=(refs[at%(sizeof refs/sizeof refs[0])]-1)%g_shm->patient_count;int id=g_shm->p[slot].id;int fh=fifo_access(&g_shm->fifo,id),lh=lru_access(&g_shm->lru,id);if(fh)g_shm->fifo_hits++;else g_shm->fifo_misses++;if(lh)g_shm->lru_hits++;else g_shm->lru_misses++;event_log("CACHE",id,"FIFO=%s LRU=%s",fh?"hit":"miss",lh?"hit":"miss");sem_post(&g_shm->cache_mutex);return slot;}
static void init(CacheState*s,int n){s->size=n;s->next=0;s->clock=0;for(int i=0;i<MAX_PATIENTS;i++){s->frames[i]=-1;s->stamp[i]=0;}}
int cache_demo(void){const int r[]={1,2,3,4,2,1,5,6,2,1,2,3,7,6,3,2,1,2,3,6};int n=(int)(sizeof r/sizeof r[0]);CacheState f,l;init(&f,3);init(&l,3);int ff=0,lf=0;puts("Page | FIFO result/frames | LRU result/frames");for(int i=0;i<n;i++){int fh=fifo_access(&f,r[i]),lh=lru_access(&l,r[i]);ff+=!fh;lf+=!lh;printf("%4d | %5s [%d %d %d] | %5s [%d %d %d]\n",r[i],fh?"hit":"fault",f.frames[0],f.frames[1],f.frames[2],lh?"hit":"fault",l.frames[0],l.frames[1],l.frames[2]);}int of=optimal_faults(r,n,3);printf("FIFO: faults=%d hits=%d\nLRU: faults=%d hits=%d\nOptimal: faults=%d hits=%d\n",ff,n-ff,lf,n-lf,of,n-of);return(ff==16&&lf==15&&of==11)?0:1;}
